package guardcore

import (
	"encoding/json"
	"os"
	"testing"
)

// The tables under testdata/ are generated by running the reference
// extract_client_ip and _ip_in_list (guard-core Python, _utils/ip_extraction.py
// and _utils/access_control.py) over each input, never hand-written.

type clientIPCase struct {
	Host     *string  `json:"host"`
	XFF      *string  `json:"xff"`
	TP       []string `json:"tp"`
	Depth    int      `json:"depth"`
	Expected string   `json:"expected"`
}

type ipListCase struct {
	IP        string   `json:"ip"`
	Canonical string   `json:"canonical"`
	Entries   []string `json:"entries"`
	Expected  bool     `json:"expected"`
}

func loadJSON(t *testing.T, name string, out any) {
	t.Helper()
	raw, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatalf("read %s: %v", name, err)
	}
	if err := json.Unmarshal(raw, out); err != nil {
		t.Fatalf("parse %s: %v", name, err)
	}
}

func TestClientIPMatchesReference(t *testing.T) {
	var cases []clientIPCase
	loadJSON(t, "client_ip_cases.json", &cases)
	if len(cases) < 85 {
		t.Fatalf("expected at least 85 reference rows, got %d", len(cases))
	}
	for i, c := range cases {
		resetForwardedWarnings()
		host, xff := "", ""
		if c.Host != nil {
			host = *c.Host
		}
		if c.XFF != nil {
			xff = *c.XFF
		}
		cfg := DefaultSecurityConfig()
		cfg.TrustedProxies = c.TP
		cfg.TrustedProxyDepth = c.Depth
		req := xffRequest("/api", host, xff)
		got := extractClientIP(req, cfg)
		// The engine reports a request with no resolvable identity as the
		// empty string; the reference names it "unknown".
		if got == "" {
			got = UnknownClientIdentity
		}
		if got != c.Expected {
			t.Errorf("row %d host=%v xff=%v tp=%v depth=%d: extract got %q, reference %q", i, host, xff, c.TP, c.Depth, got, c.Expected)
		}
		seen := resolveClientIP(req)
		if seen == "" {
			seen = UnknownClientIdentity
		}
		if seen != c.Expected {
			t.Errorf("row %d host=%v xff=%v tp=%v depth=%d: consumers see %q, reference %q", i, host, xff, c.TP, c.Depth, seen, c.Expected)
		}
	}
}

func TestIPListMatchingMatchesReference(t *testing.T) {
	var cases []ipListCase
	loadJSON(t, "client_ip_lists.json", &cases)
	for i, c := range cases {
		// The pipeline matches the canonical identity; the raw spelling
		// must reach the same verdict because the matcher canonicalizes.
		for _, ip := range []string{c.Canonical, c.IP} {
			if got := ipMatchesList(ip, c.Entries); got != c.Expected {
				t.Errorf("row %d ip=%q entries=%v: got %v, reference %v", i, ip, c.Entries, got, c.Expected)
			}
		}
	}
}

func clientIPEngine(t *testing.T, mutate func(*SecurityConfig)) *Engine {
	t.Helper()
	cfg, err := NewSecurityConfig(func(c *SecurityConfig) {
		c.EnableRedis = false
		c.EnableRateLimiting = false
		if mutate != nil {
			mutate(c)
		}
	})
	if err != nil {
		t.Fatal(err)
	}
	engine, err := NewEngine(cfg)
	if err != nil {
		t.Fatal(err)
	}
	return engine
}

func engineStatus(engine *Engine, req Request) int {
	if resp := engine.Check(req); resp != nil {
		return resp.StatusCode
	}
	return 200
}

// TestEngineBlacklistBlocksIPv4MappedClient: a client that connects as
// ::ffff:<ipv4> (a dual-stack listener) is the IPv4 identity, so an IPv4
// blacklist entry or IPv4 CIDR blocks it.
func TestEngineBlacklistBlocksIPv4MappedClient(t *testing.T) {
	for _, entry := range []string{"127.0.0.1", "127.0.0.0/8", "::ffff:127.0.0.1"} {
		engine := clientIPEngine(t, func(c *SecurityConfig) { c.Blacklist = []string{entry} })
		for _, peer := range []string{"127.0.0.1", "::ffff:127.0.0.1"} {
			if got := engineStatus(engine, xffRequest("/api", peer, "")); got != 403 {
				t.Errorf("blacklist %q peer %q: status %d, want 403", entry, peer, got)
			}
		}
		if got := engineStatus(engine, xffRequest("/api", "::ffff:203.0.113.9", "")); got != 200 {
			t.Errorf("blacklist %q must not block another client, got %d", entry, got)
		}
	}
}

func TestEngineWhitelistAdmitsIPv4MappedClient(t *testing.T) {
	engine := clientIPEngine(t, func(c *SecurityConfig) { c.Whitelist = []string{"10.0.0.0/8"} })
	if got := engineStatus(engine, xffRequest("/api", "::ffff:10.1.1.1", "")); got != 200 {
		t.Errorf("whitelisted mapped client: status %d, want 200", got)
	}
	if got := engineStatus(engine, xffRequest("/api", "::ffff:203.0.113.9", "")); got != 403 {
		t.Errorf("non-whitelisted mapped client: status %d, want 403", got)
	}
}

func TestEngineBanBlocksIPv4MappedClient(t *testing.T) {
	engine := clientIPEngine(t, func(c *SecurityConfig) { c.EnableIPBanning = true })
	if _, err := engine.Ban.Ban("198.51.100.7", 300, "test"); err != nil {
		t.Fatal(err)
	}
	for _, peer := range []string{"198.51.100.7", "::ffff:198.51.100.7"} {
		if got := engineStatus(engine, xffRequest("/api", peer, "")); got != 403 {
			t.Errorf("banned peer %q: status %d, want 403", peer, got)
		}
	}
}

func TestEngineEmergencyWhitelistAdmitsIPv4MappedClient(t *testing.T) {
	engine := clientIPEngine(t, func(c *SecurityConfig) {
		c.EmergencyMode = true
		c.EmergencyWhitelist = []string{"198.51.100.9"}
	})
	if got := engineStatus(engine, xffRequest("/api", "::ffff:198.51.100.9", "")); got != 200 {
		t.Errorf("emergency-whitelisted mapped client: status %d, want 200", got)
	}
	if got := engineStatus(engine, xffRequest("/api", "::ffff:198.51.100.10", "")); got == 200 {
		t.Errorf("emergency mode must deny other clients")
	}
}

func TestEngineStoresCanonicalIdentity(t *testing.T) {
	engine := clientIPEngine(t, nil)
	req := xffRequest("/api", "::ffff:203.0.113.9", "")
	engine.Check(req)
	if got := req.State().ClientIP; got != "203.0.113.9" {
		t.Errorf("state client ip %q, want 203.0.113.9", got)
	}
}

func TestEngineForwardedChainIdentityReachesEveryCheck(t *testing.T) {
	engine := clientIPEngine(t, func(c *SecurityConfig) {
		c.TrustedProxies = []string{"127.0.0.1"}
		c.Blacklist = []string{"203.0.113.77"}
	})
	req := xffRequest("/api", "127.0.0.1", "::ffff:203.0.113.77")
	if got := engineStatus(engine, req); got != 403 {
		t.Errorf("blacklisted forwarded client: status %d, want 403", got)
	}
	if got := req.State().ClientIP; got != "203.0.113.77" {
		t.Errorf("state client ip %q, want 203.0.113.77", got)
	}
}

func TestEngineUnixTrustedProxyResolvesWithoutPeer(t *testing.T) {
	engine := clientIPEngine(t, func(c *SecurityConfig) {
		c.TrustedProxies = []string{"unix"}
		c.Blacklist = []string{"203.0.113.31"}
	})
	req := xffRequest("/api", "", "203.0.113.31")
	if got := engineStatus(engine, req); got != 403 {
		t.Errorf("blacklisted client behind a unix proxy: status %d, want 403", got)
	}
	if got := req.State().ClientIP; got != "203.0.113.31" {
		t.Errorf("state client ip %q, want 203.0.113.31", got)
	}
}
